package com.example.solarfarm.service;
import com.example.solarfarm.domain.Farm; import com.example.solarfarm.repository.FarmRepository; import com.example.solarfarm.common.Dtos; import org.springframework.stereotype.Service; import java.util.List;
@Service public class FarmService { private final FarmRepository farms; public FarmService(FarmRepository f){farms=f;} public List<Dtos.FarmResponse> all(){return farms.findAll().stream().map(this::map).toList();} public Dtos.FarmResponse one(Long id){return map(farms.findById(id).orElseThrow());} public Farm createDefault(){return farms.findAll().stream().findFirst().orElseGet(()->farms.save(new Farm("Virtual Solar Farm","Phase 6 virtual topology",20,25,500)));} private Dtos.FarmResponse map(Farm f){return new Dtos.FarmResponse(f.getId(),f.getName(),f.getDescription(),f.getRows(),f.getColumns(),f.getPanelCount());} }
